def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        if no_water >= 2 or hp <= 3:
            safe_bid = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe_bid)))

    yesterday_bids = []
    urgent_bids = []
    max_opp_budget = 0.0
    urgent_count = 0
    for oid, opp in alive:
        max_opp_budget = max(max_opp_budget, float(opp.get('budget', 0.0)))
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
            urgent_count += 1
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            pbid = float(pbid)
            yesterday_bids.append(pbid)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_bids.append(pbid)

    slots = max(1, int(supply // WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    base = DAILY_SALARY * 0.42

    if scarcity >= 3:
        base = DAILY_SALARY * 0.82
    elif scarcity == 2:
        base = DAILY_SALARY * 0.68
    elif scarcity == 1:
        base = DAILY_SALARY * 0.56
    else:
        base = DAILY_SALARY * 0.38

    if no_water >= 2 or hp <= 2:
        base = max(base, DAILY_SALARY * 0.96)
    elif no_water >= 1 or hp <= 4:
        base = max(base, DAILY_SALARY * 0.78)
    elif hp >= 8 and supply >= 24:
        base = min(base, DAILY_SALARY * 0.34)

    if yesterday_bids:
        high_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        if scarcity >= 2:
            target = max(base, min(high_prev + 2.0, DAILY_SALARY * 1.18))
        else:
            target = max(base, min(avg_prev + 1.0, DAILY_SALARY * 0.72))
        base = target

    if urgent_bids and scarcity >= 1:
        base = max(base, min(max(urgent_bids) + 1.5, DAILY_SALARY * 1.22))

    if urgent_count >= slots and scarcity >= 1:
        base = max(base, DAILY_SALARY * 0.88)

    if day >= 8 and hp >= 6 and no_water == 0:
        base *= 0.92

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget)
    elif budget > max_opp_budget + DAILY_SALARY and hp >= 5 and scarcity >= 2:
        base = max(base, DAILY_SALARY * 0.9)

    bid = max(0.0, min(float(budget), float(base)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not yesterday_bids:
        return min(my_status['budget'], 110.0)

    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] < 5:
        return min(my_status['budget'], max_prev * 1.1 + 5.0)

    if day_context['supply'] < 18:
        return min(my_status['budget'], max_prev + 10.0)

    return min(my_status['budget'], avg_prev + 5.0)
